package com.smartsociety.platform.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; import java.security.Key; import java.time.Instant; import java.util.*;
@Service public class JwtService { private final Key key; private final long exp; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.expiration-minutes}") long exp){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.exp=exp;} public String create(UUID id,String email,String role){var now=Instant.now();return Jwts.builder().subject(email).claim("uid",id.toString()).claim("role",role).issuedAt(Date.from(now)).expiration(Date.from(now.plusSeconds(exp*60))).signWith(key).compact();} public Claims parse(String token){return Jwts.parser().verifyWith((javax.crypto.SecretKey)key).build().parseSignedClaims(token).getPayload();} }
